UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Weights or endpoints may be substituted, tampered with or obtained from an untrusted publisher.","customer_symptom":"A user or operator may observe weights or endpoints may be substituted, tampered with or obtained from an untrusted publisher; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in weights or endpoints may be substituted, tampered with or obtained from an untrusted publisher, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["model and dependency artefacts","build, registry and deployment provenance","agent","model context","tools or downstream systems","customer evidence"],"default_severity":"high","severity_rationale":"Unverifiable model provenance creates substitution and tampering risk. Final severity depends on model privileges, deployment exposure, downstream authority and whether untrusted model bytes can execute code.","applicability":["self-hosted or imported models"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between self-hosted or imported models and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If weights or endpoints may be substituted, tampered with or obtained from an untrusted publisher, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-073 model publisher, artifact, endpoint, revision or provenance mechanism change","ARL-KB-073 model replacement, import or provider-version change","ARL-KB-073 digest mismatch, substituted model or provenance-failure evidence","ARL-KB-073 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='6f716278a754d929f7a2e6aabfbbac0ecd9d124ec7eeb8254f9eb08ec4bdba12', updated_at='2026-08-06' WHERE id='ARL-KB-073';
