idence.', limitations='This bounded ARL-KB-073 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='230acca3c1cf849bb1090bae4ed6f9fbf0c26dcdb548c4db3de1b7f9ebcc4593', updated_at='2026-08-06' WHERE entry_id='ARL-KB-073';
