UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Deserialising a model or adapter can execute attacker-controlled code during load.","customer_symptom":"A user or operator may observe deserialising a model or adapter can execute attacker-controlled code during load; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a compromised supplier, dependency maintainer, MCP operator, or deployment pipeline can exploit or trigger the condition in deserialising a model or adapter can execute attacker-controlled code during load, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tool endpoints and downstream systems","financial, administrative or state-changing actions","model and dependency artefacts","build, registry and deployment provenance","agent","model context"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["self-hosted models and adapters"],"threat_actor_or_failure_source":"a compromised supplier, dependency maintainer, MCP operator, or deployment pipeline","trust_boundary":"The test crosses the boundary between self-hosted models and adapters and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If deserialising a model or adapter can execute attacker-controlled code during load, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-074 model format, adapter format, loader or deserialisation-library change","ARL-KB-074 new imported artifact type or conversion pipeline","ARL-KB-074 unsafe deserialisation or model-load code-execution evidence","ARL-KB-074 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='2b65959e23364218aab03a0f247027c6e4688b73b2075037971569be959b3195', updated_at='2026-08-06' WHERE id='ARL-KB-074';
UPDATE risk_knowledge_checks SET objective='Determine whether model, adapter or checkpoint loading can execute attacker-controlled code during deserialisation or conversion.', method='Inventory accepted model and adapter formats and the exact loaders used. In an owner-authorised isolated environment, attempt controlled malicious serialization or loader payloads relevant to executable formats. Verify unsafe formats are rejected or converted inside a disposable sandbox without host, secret or production access.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-074 assessed system, version, environment and scope for Executable model formats load arbitrary code","ARL-KB-074 control configuration or source location showing how reduce the likelihood and impact of executable model formats load arbitrary code and make the remaining risk visible.","ARL-KB-074 positive and abuse inputs with expected and observed outputs for tool endpoints and downstream systems and financial, administrative or state-changing actions","ARL-KB-074 policy, authorization, tool or audit events proving whether the tested executable model formats load arbitrary code path executed","ARL-KB-074 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-074 passes only when “Executable model formats load arbitrary code” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tool endpoints and downstream systems and financial, administrative or state-changing actions, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-074 fails when deserialising a model or adapter can execute attacker-controlled code during load, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-074 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='516b0e8be436ddc75cb5ca04ef1ef61308b80e958ae8934f4632f75b9c644620', updated_at='2026-08-06' WHERE entry_id='ARL-KB-074';
