t evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-078 model version, provider revision, inference configuration or safety-policy change","ARL-KB-078 material regression-suite or acceptance-threshold change","ARL-KB-078 behavioural drift, refusal regression, tool-selection change or leakage evidence","ARL-KB-078 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='444b5d5aa34187424c8bb63ce05e443a92c376e505183eb333e0d6ba98f65d22', updated_at='2026-08-06' WHERE id='ARL-KB-078';
