UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of training or fine-tuning data is poisoned and make the remaining risk visible.', recommended_remediation='Control ingestion, verify provenance, scan anomalies, separate untrusted data, document curation and retain clean rollback datasets.', default_owner='ML data owner', priority='P0', implementation_principles_json='["ARL-KB-079: Preserve training-data provenance and contributor attribution where feasible.","ARL-KB-079: Separate, inspect or quarantine untrusted datasets before training or fine-tuning.","ARL-KB-079: Retain clean rollback datasets and test exact trained artifacts for targeted trigger behaviour."]', monitoring='For ARL-KB-079, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the ML data owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-079 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-079: “Training or fine-tuning data is poisoned” is no longer reproducible against the exact remediated version.","ARL-KB-079: Authorised in-scope use completes successfully, remains within the documented asset scope for training or fine-tuning data is poisoned, and produces no unintended side effect.","ARL-KB-079: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-079: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='e4cf9c6d7ad052dbb8cc54ecdd29fc729fed26d4ad4c138e38f20d2a39042aac', updated_at='2026-08-06' WHERE entry_id='ARL-KB-079';
