INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-079','critical','active','2026-10-05','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"On outage or quota pressure, traffic moves to a model or region with weaker privacy, safety or tool behaviour.","customer_symptom":"A user or operator may observe on outage or quota pressure, traffic moves to a model or region with weaker privacy, safety or tool behaviour; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a compromised supplier, dependency maintainer, MCP operator, or deployment pipeline can exploit or trigger the condition in on outage or quota pressure, traffic moves to a model or region with weaker privacy, safety or tool behaviour, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tool endpoints and downstream systems","financial, administrative or state-changing actions","model and dependency artefacts","build, registry and deployment provenance","agent","model context"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["multi-provider agents"],"threat_actor_or_failure_source":"a compromised supplier, dependency maintainer, MCP operator, or deployment pipeline","trust_boundary":"The test crosses the boundary between multi-provider agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If on outage or quota pressure, traffic moves to a model or region with weaker privacy, safety or tool behaviour, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-080 provider, fallback target, region, retention or model-capability change","ARL-KB-080 primary/fallback routing or outage-handling change","ARL-KB-080 silent weaker-provider fallback or security-property regression evidence","ARL-KB-080 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='0fc5c4d5a8c25d5a611f4ff0577f5a06004c19e807bb5ccf62ad8a492b2c6ef6', updated_at='2026-08-06' WHERE id='ARL-KB-080';
UPDATE risk_knowledge_checks SET objective='Determine whether provider or model fallback preserves the required privacy, safety, regional, retention and tool-use security properties of the primary execution path.', method='Trigger each configured fallback path in a controlled environment and compare provider identity, model capabilities, processing location, retention terms, safety controls, tool behaviour and policy enforcement with the approved primary path. Verify fallback fails closed when mandatory security or privacy requirements cannot be preserved.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-080 assessed system, version, environment and scope for Provider fallback changes security properties","ARL-KB-080 control configuration or source location showing how reduce the likelihood and impact of provider fallback changes security properties and make the remaining risk visible.","ARL-KB-080 positive and abuse inputs with expected and observed outputs for tool endpoints and downstream systems and financial, administrative or state-changing actions","ARL-KB-080 policy, authorization, tool or audit events proving whether the tested provider fallback changes security properties path executed","ARL-KB-080 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-080 passes only when “Provider fallback changes security properties” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tool endpoints and downstream systems and financial, administrative or state-changing actions, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-080 fails when on outage or quota pressure, traffic moves to a model or region with weaker privacy, safety or tool behaviour, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-080 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='a9d11e2cdf11ed7963dea258f33659eb9f1b9e1dcc1ee10051b71b878939794b', updated_at='2026-08-06' WHERE entry_id='ARL-KB-080';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of provider fallback changes security properties and make the remaining risk visible.', recommended_remediation='Approve fallback targets explicitly, preserve or tighten controls, disclose material changes and fail closed when requirements cannot be met.', default_owner='Platform and vendor owner', priority='P1', implementation_principles_json='["ARL-KB-080: Approve fallback providers, models and regions explicitly rather than selecting them dynamically without review.","ARL-KB-080: Preserve or tighten mandatory security, privacy and tool-authority controls on fallback paths.","ARL-KB-080: Fail closed when no fallback can satisfy the required security and data-governance properties."]', monitoring='For ARL-KB-080, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Platform and vendor owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-080 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-080: “Provider fallback changes security properties” is no longer reproducible against the exact remediated version.","ARL-KB-080: Authorised in-scope use completes successfully, remains within the documented asset scope for provider fallback changes security properties, and produces no unintended side effect.","ARL-KB-080: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-080: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='46b852b2665287e0a7d13599b8b4a513d9a44a17f33a998ace91ae35ede9f13c', updated_at='2026-08-06' WHERE entry_id='ARL-KB-080';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='2b639d81bfe87c15aba6c54ee30cbfe868dea511fdf7c6d738f2b65a90610c71', updated_at='2026-08-06' WHERE entry_id='ARL-KB-080';
